INSERT INTO "Movies" ("Movie_ID", "Movie_Name", "Release_Date", "End_Date", "Production_Company", "Director", "Cast", "Duration", "Genre", "Rating", "Language", "Country", "Synopsis", "Poster_URL", "Trailer_Link", "Status", "Created_By", "Created_At", "Updated_At") OVERRIDING SYSTEM VALUE VALUES
(1, 'Avengers: Endgame', '2024-08-01 00:00:00', '2026-12-31 00:00:00', 'Marvel Studios', 'Anthony Russo, Joe Russo', 'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth', 181, 'Action, Adventure, Sci-Fi', 'PG-13', 'English', 'USA', 'Sau sự kiện Infinity War, các Avengers hợp sức để đánh bại Thanos và cứu vũ trụ khỏi sự hủy diệt.', 'https://image.tmdb.org/t/p/w500/or06FN3Dka5tukK1e9sl16pB3iy.jpg', 'https://www.youtube.com/watch?v=TcMBFSGVi1c', 'Now Showing', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(2, 'Spider-Man: No Way Home', '2024-08-10 00:00:00', '2026-12-31 00:00:00', 'Sony Pictures', 'Jon Watts', 'Tom Holland, Zendaya, Benedict Cumberbatch, Jamie Foxx', 148, 'Action, Adventure, Fantasy', 'PG-13', 'English', 'USA', 'Peter Parker nhờ Doctor Strange thực hiện phép thuật để xóa danh tính Spider-Man, nhưng mọi thứ trở nên hỗn loạn.', 'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', 'https://www.youtube.com/watch?v=JfVOs4VSpmA', 'Now Showing', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(3, 'Inception', '2024-07-15 00:00:00', '2026-12-31 00:00:00', 'Warner Bros.', 'Christopher Nolan', 'Leonardo DiCaprio, Joseph Gordon-Levitt, Elliot Page, Tom Hardy', 148, 'Action, Sci-Fi, Thriller', 'PG-13', 'English', 'USA', 'Một tên trộm tài ba đi vào tâm trí người khác để đánh cắp bí mật nhận nhiệm vụ nguy hiểm nhất: trồng ý tưởng.', 'https://image.tmdb.org/t/p/w500/9gk7adHYeDvHkCSEqAvQNLV5Uge.jpg', 'https://www.youtube.com/watch?v=YoHD9XEInc0', 'Now Showing', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(4, 'Interstellar', '2026-09-01 00:00:00', '2026-11-30 00:00:00', 'Paramount Pictures', 'Christopher Nolan', 'Matthew McConaughey, Anne Hathaway, Jessica Chastain, Michael Caine', 169, 'Adventure, Drama, Sci-Fi', 'PG', 'English', 'USA', 'Nhóm phi hành gia đi qua lỗ sâu trong vũ trụ để tìm kiếm ngôi nhà mới cho nhân loại trước khi Trái Đất diệt vong.', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', 'https://www.youtube.com/watch?v=zSWdZVtXT7E', 'Coming Soon', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(5, 'The Dark Knight', '2026-10-01 00:00:00', '2026-12-31 00:00:00', 'Warner Bros.', 'Christopher Nolan', 'Christian Bale, Heath Ledger, Aaron Eckhart, Maggie Gyllenhaal', 152, 'Action, Crime, Drama', 'PG-13', 'English', 'USA', 'Batman phải đối mặt với Joker - tên tội phạm hỗn loạn muốn nhấn chìm Gotham City vào hỗn mang.', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', 'https://www.youtube.com/watch?v=EXeTwQWrcwY', 'Coming Soon', 1, '2026-08-17 14:38:46', '2026-08-17 14:38:46'),
(18, 'Mission: Impossible – Tối Hậu Thư', '2026-05-23 00:00:00', '2026-12-31 00:00:00', 'Paramount Pictures', 'Christopher McQuarrie', 'Tom Cruise, Hayley Atwell, Ving Rhames, Simon Pegg', 163, 'Action,Thriller', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Ethan Hunt và nhóm IMF đối mặt với mối đe dọa nguy hiểm nhất từ trước đến nay — một thực thể AI bí ẩn có thể kiểm soát toàn bộ hệ thống vũ khí hạt nhân thế giới.', 'https://image.tmdb.org/t/p/w500/iKPsC9EFUafRP9SrUznI61getVP.jpg', 'https://www.youtube.com/watch?v=fsQgc9pCyDU', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(19, 'Thunderbolts*', '2026-05-02 00:00:00', '2026-12-31 00:00:00', 'Marvel Studios', 'Jake Schreier', 'Florence Pugh, Sebastian Stan, David Harbour, Wyatt Russell, Julia Louis-Dreyfus', 127, 'Action,Superhero,Adventure', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Một nhóm nhân vật phản anh hùng bị ép buộc phải hợp tác để thực hiện một nhiệm vụ tự sát cho chính phủ.', 'https://image.tmdb.org/t/p/w500/hqcexYHbiTBfDIdDWxrxPtVndBX.jpg', 'https://www.youtube.com/watch?v=-sAOWhvheK8', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(20, 'Materialists', '2026-06-13 00:00:00', '2026-12-31 00:00:00', 'A24', 'Celine Song', 'Dakota Johnson, Chris Evans, Pedro Pascal', 100, 'Romance,Drama', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Một người chuyên mai mối quyền lực ở New York bị kéo vào cuộc tình phức tạp giữa người cũ giàu có và người mới đơn giản.', 'https://image.tmdb.org/t/p/w500/eDo0pNruy0Qgj6BdTyHIR4cxHY8.jpg', 'https://www.youtube.com/watch?v=9gjeXsTsxqY', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(21, 'Jurassic World: Tái Sinh', '2026-07-02 00:00:00', '2026-12-31 00:00:00', 'Universal Pictures', 'Gareth Edwards', 'Scarlett Johansson, Jonathan Bailey, Mahershala Ali', 120, 'Adventure,Sci-Fi,Action', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Năm năm sau sự kiện thảm khốc ở Dominion, một nhóm khoa học bí mật xâm nhập vào khu vực cách ly để thu thập ADN khủng long.', 'https://image.tmdb.org/t/p/w500/1RICxzeoNCAO5NpcRMIgg1XT6fm.jpg', 'https://www.youtube.com/watch?v=jan5CFWs9ic', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(22, 'F1: Tốc Độ Huyền Thoại', '2026-06-27 00:00:00', '2026-12-31 00:00:00', 'Apple Original Films', 'Joseph Kosinski', 'Brad Pitt, Damson Idris, Kerry Condon, Javier Bardem', 130, 'Action,Drama,Sport', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Một tay đua huyền thoại quay trở lại đường đua F1 để hướng dẫn một tài năng trẻ, cùng nhau đối mặt với những đối thủ hùng mạnh và áp lực khổng lồ.', 'https://image.tmdb.org/t/p/w500/9PXZIUsSDh4alB80jheWX4fhZmy.jpg', 'https://www.youtube.com/watch?v=CT2_P2DZBR0', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(23, 'Bí Kíp Luyện Rồng: Live Action', '2026-06-13 00:00:00', '2026-12-31 00:00:00', 'DreamWorks Animation/Universal', 'Dean DeBlois', 'Mason Thames, Nico Parker, Gerard Butler', 110, 'Adventure,Family,Fantasy', 'PG', 'Tiếng Anh (Lồng tiếng Việt)', 'USA', 'Phiên bản người đóng của bộ phim hoạt hình kinh điển — chàng trai Viking Hiccup và chú rồng đêm không đuôi Toothless.', 'https://image.tmdb.org/t/p/w500/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', 'https://www.youtube.com/watch?v=22w7z_lT6YM', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(24, 'Điểm Đến Cuối Cùng: Huyết Thống', '2026-05-16 00:00:00', '2026-12-31 00:00:00', 'New Line Cinema', 'Zach Lipovsky, Adam Stein', 'Kaitlyn Santa Juana, Teo Briones, Richard Harmon', 110, 'Horror,Thriller', 'R', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Một sinh viên đại học nhận ra cô có thể nhìn thấy cái chết trước khi nó xảy ra — giống như một tổ tiên của mình nhiều thập kỷ trước.', 'https://image.tmdb.org/t/p/w500/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', 'https://www.youtube.com/watch?v=xitSoRbHJ50', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(25, 'Kẻ Tội Đồ', '2026-04-18 00:00:00', '2026-12-31 00:00:00', 'Warner Bros. Pictures', 'Ryan Coogler', 'Michael B. Jordan, Hailee Steinfeld, Jack O''Connell', 137, 'Horror,Drama', 'R', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Hai anh em sinh đôi trở về miền Nam nước Mỹ sau Thế chiến I để xây dựng cuộc sống mới, nhưng thay vào đó lại đối mặt với một thứ kinh khủng hơn cả chiến tranh.', 'https://image.tmdb.org/t/p/w500/fWPgbnt2LSqkQ6cdQc0SZN9CpLm.jpg', 'https://www.youtube.com/watch?v=O98jSd24lmA', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(26, 'Superman', '2026-07-11 00:00:00', '2026-10-15 00:00:00', 'DC Studios/Warner Bros.', 'James Gunn', 'David Corenswet, Rachel Brosnahan, Nicholas Hoult, Edi Gathegi', 130, 'Action,Superhero,Adventure', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Chương đầu tiên của Vũ trụ DC mới — Clark Kent đang học cách cân bằng di sản Kryptonian với bản sắc con người của mình khi đối mặt với Lex Luthor.', 'https://image.tmdb.org/t/p/w500/ldyfo0BKmz5rWtJJKCvwaNS4cJT.jpg', 'https://www.youtube.com/watch?v=Ox8ZLF6cGM0', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(27, 'Vũ Nữ Sát Thủ', '2026-06-06 00:00:00', '2026-12-31 00:00:00', 'Lionsgate', 'Len Wiseman', 'Ana de Armas, Keanu Reeves, Anjelica Huston, Ian McShane', 118, 'Action,Thriller', 'R', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Eve Macarro lớn lên trong Ruska Roma và trở thành một sát thủ để trả thù cho cái chết của cha mình.', 'https://image.tmdb.org/t/p/w500/2VUmvqsHb6cEtdfscEA6fqqVzLg.jpg', 'https://www.youtube.com/watch?v=0FSwsrFpkbw', 'Now Showing', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(28, 'Avatar: Lửa và Tro', '2026-12-19 00:00:00', NULL, '20th Century Studios', 'James Cameron', 'Sam Worthington, Zoe Saldana, Sigourney Weaver, Kate Winslet', 180, 'Sci-Fi,Adventure,Action', 'PG-13', 'Tiếng Anh (Lồng tiếng Việt)', 'USA', 'Tiếp theo của Avatar: The Way of Water — gia đình Sully tiếp tục cuộc hành trình trên Pandora.', 'https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', 'https://www.youtube.com/watch?v=ITmRYfeg4H0', 'Coming Soon', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04'),
(29, 'Black Panther: Chiến Dịch Mới', '2026-11-06 00:00:00', NULL, 'Marvel Studios', 'Denys Couch', 'Letitia Wright, Lupita Nyong''o, Winston Duke', 130, 'Superhero,Action,Adventure', 'PG-13', 'Tiếng Anh (Phụ đề Việt)', 'USA', 'Shuri tiếp tục gánh vác vai trò Black Panther trong một cuộc xung đột toàn cầu mới.', 'https://image.tmdb.org/t/p/w500/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', 'https://www.youtube.com/watch?v=_Z3QKkl1WyM', 'Coming Soon', 1, '2026-08-18 23:47:31', '2026-10-07 16:12:04');
